// Generated by scripts/speed.js. Keeps the app on the phone for fast repeat opens and offline use.
const CACHE = "rolodex-2e99ffdd3dc8";
const BASE = "/life-long-logbook";
const PRECACHE = [
  "/life-long-logbook/",
  "/life-long-logbook/_expo/static/js/web/index-8f025c1c5607da1eeaed5039cd975e2e.js",
  "/life-long-logbook/manifest.webmanifest",
  "/life-long-logbook/assets/node_modules/@expo-google-fonts/lora/400Regular/Lora_400Regular.7637dfac7457920e0367967d608ee3a8.ttf",
  "/life-long-logbook/assets/node_modules/@expo-google-fonts/lora/600SemiBold/Lora_600SemiBold.9a334f12e5bb77aa5827ed4029b3cafa.ttf",
  "/life-long-logbook/assets/node_modules/@expo-google-fonts/patrick-hand/400Regular/PatrickHand_400Regular.0b94e62171b862ddb28135554050f315.ttf"
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE)
      // the page is always fetched fresh; the other files have a content hash in their name, so a saved copy is always right
      .then((cache) => cache.addAll(PRECACHE.map((u) => (u === BASE + "/" ? new Request(u, { cache: "reload" }) : u))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("rolodex-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== location.origin || !url.pathname.startsWith(BASE + "/")) return;
  if (url.pathname === BASE + "/sw.js") return;
  event.respondWith(request.mode === "navigate" ? openPage() : savedFirst(request));
});

// The page: ask the network first so updates arrive at once, but give up after 4 seconds (or offline)
// and use the saved copy.
async function openPage() {
  const cache = await caches.open(CACHE);
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 4000);
    const response = await fetch(BASE + "/", { cache: "no-cache", signal: controller.signal });
    clearTimeout(timer);
    if (response.ok) cache.put(BASE + "/", response.clone());
    return response;
  } catch (e) {
    return (await cache.match(BASE + "/")) || Response.error();
  }
}

// Code, fonts and icons: use the saved copy if there is one, otherwise fetch it and save it.
async function savedFirst(request) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok && response.type === "basic") cache.put(request, response.clone());
  return response;
}
